import csv
import re
import io

data = """"Burkhan Khaldun (Yasak Dağ)","Khentii","Moğolistan","Cengiz Han'ın gizli mezarının bulunduğuna inanılan ve asırlardır kadim şamanlar ile görünmez varlıklar tarafından korunan bu kutsal ve yasak dağ. Bölgeye izinsiz yaklaşanların aurasını anında ezen o devasa, ilkel (primal) imparatorluk frekansı ve gece rüzgarına karışan savaşçı atlarının toynak sesleri insanın kanını dondurur.",5"Ongi Manastırı Harabeleri","Dundgovi","Moğolistan","1930'lardaki kanlı tasfiyeler sırasında yüzlerce Budist rahibin (Lama) kurşuna dizilerek ve tapınaklarıyla birlikte yakılarak katledildiği Gobi çölündeki bu harabeler. Yıkıntıların arasında durduğunuzda, havada asılı kalan o paslı kan kokusunu ve haksız yere ölenlerin o ezici, melankolik keder frekansını tüm çakralarınızda hissedersiniz.",5"Darkhad Vadisi (Kara Şamanlar Vadisi)","Khövsgöl","Moğolistan","Moğolistan'ın en izole, en soğuk ve en güçlü kara şamanlarının yaşadığı bu uçsuz bucaksız vadi. Geceleri yakılan ateşlerin etrafında boyut kapılarının ardına kadar açıldığı bu topraklarda, davul seslerine karışan alt boyut varlıklarının fısıltıları zihninizi sarar; buranın doğası insanı açıkça reddeden karanlık bir zekaya sahiptir.",5"Karakorum (Kadim Başkent Harabeleri)","Övörkhangai","Moğolistan","Dünyanın yarısına hükmetmiş Moğol İmparatorluğu'nun yıkılmış ve toprağa gömülmüş eski başkenti. Bozkırın ortasındaki bu yalnız harabelerde gece çöktüğünde, kılıç sesleri ve fetihlerde akan milyonlarca insanın kanından beslenen o kaotik savaş travması uyanır; eski gücün o hayalet frekansı nefesinizi keser.",4"Songino Khairkhan Toplu Mezarları","Ulan Batur","Moğolistan","Başkentin eteklerinde yer alan, on binlerce aydının ve siyasi mahkumun gizlice kurşuna dizilip gömüldüğü bu karanlık ve soğuk tepeler. Toprağın altında yatan ihanetin ve toplu ölüm korkusunun yarattığı o ağır, çürümüş enerji, alana adım atanların göğsüne kurşun gibi oturarak ağır bir anksiyete atağına sebep olur.",5"Khövsgöl Gölü (Ruhlar Denizi)","Khövsgöl","Moğolistan","Asırlardır şamanların adaklar adadığı ve 'Su Ana' ruhuna tapındığı, kışın metrelerce buz tutan bu devasa ve dipsiz göl. Buzların çatlama sesinin insan çığlıklarını andırdığı kış gecelerinde, suyun zifiri karanlık derinliklerinden gelen o hipnotik ve yutucu astral çekim gücü, insanın iradesini tamamen felç eder.",4"Yol Vadisi (Yolyn Am)","Ömnögovi","Moğolistan","Gobi çölünün ortasında yer almasına rağmen güneş ışığının asla dibine ulaşamadığı ve yazın bile buzlarla kaplı olan bu klostrofobik kanyon. Daracık geçitlerde yürürken oksijenin çekildiğini hisseder, donarak ölen gezginlerin ve vadiyi koruyan elementallerin o soğuk, dışlayıcı fısıltılarını ensenizde duyarsınız.",4"Manzushir Manastırı (Ölüm Uçurumu)","Töv","Moğolistan","Bogd Han dağlarının sarp kayalıklarına oyulmuş ancak yine kanlı tasfiyelerde yerle bir edilip rahiplerinin uçurumlardan aşağı atıldığı bu manastır kalıntıları. Zirveden aşağı bakıldığında, düşme anındaki o saf dehşet ve çaresizlik enerjisi bir girdap (vortex) gibi sizi içine çekmeye, zihninizi uçuruma doğru çağırmaya başlar.",4"Bayanzag (Alevli Uçurumlar)","Ömnögovi","Moğolistan","Gün batımında kan kırmızısına dönen bu devasa çöl kayalıkları, kadim çağlardan beri ıssızlığın ve çöl cinlerinin av sahası olarak bilinir. Geceleri kum fırtınalarının içinden beliren devasa gölge kütleleri ve çölün o insanın yaşam enerjisini emen, kurutan devasa yalnızlık frekansı, en deneyimli psişikleri bile sarsar.",4"100 Ağaç Vadisi (Şaman Laneti)","Selenge","Moğolistan","Karanlık bir şaman tarafından lanetlendiğine inanılan ve ağaçların tamamen şekilsiz, kıvrık, adeta acı çekiyormuş gibi büyüdüğü bu tekinsiz ormanlık alan. Ormanın içine girdiğinizde cihazların pusulaları sapar; ağaçların arasından sizi izleyen görünmez gözlerin yarattığı o ağır, yırtıcı izlenme hissi auranızı adeta bıçaklar.",3"""

# Split by fixing the missing newline before a quote after a number
formatted_data = re.sub(r'(\d)"', r'\1\n"', data)

reader = csv.reader(io.StringIO(formatted_data))
with open('perili_mekanlar.csv', 'a', encoding='utf-8', newline='') as f:
    writer = csv.writer(f)
    for row in reader:
        # Avoid empty lines
        if not row:
            continue
        if len(row) == 5:
            row.append('') # resim_url
        writer.writerow(row)

print("Mogolistan kayitlari eklendi.")
